// Generated by Cypress Author on 2026-11-01 for the PHASE-07/08 diagnostic opt-in.
// Observers never supply responses, consume bodies, wait for paint or change gates.
export const phaseDiagnosticRoutes = [
  'identity',
  'class',
  'organization',
  'dashboard',
  'signals',
  'progress',
  'auth-token',
  'auth-user',
  'auth-logout',
] as const;
export const phaseDiagnosticEvents = [
  'observer:installed',
  'session:effect',
  'session:client-ready',
  'session:state',
  'identity:ready',
  'json:start',
  'json:end',
  'validation:start',
  'validation:end',
  'dom:ready',
] as const;
export type PhaseDiagnosticRoute = (typeof phaseDiagnosticRoutes)[number];
type EventName = (typeof phaseDiagnosticEvents)[number];
type DiagnosticEvent = {
  name: EventName;
  at: number;
  route?: PhaseDiagnosticRoute;
  requestId?: string;
};
type RequestSpan = {
  seq: number;
  route: PhaseDiagnosticRoute;
  method: 'GET' | 'POST' | 'OTHER';
  start: number;
  headers: number | null;
  end: number | null;
  status: number | null;
  requestId: string | null;
  outcome: 'pending' | 'fulfilled' | 'rejected';
  aborted: boolean | null;
};
type NavigationTiming = {
  startTime: number;
  responseEnd: number;
  domInteractive: number;
  domContentLoadedEventEnd: number;
  loadEventEnd: number;
};
export type PhaseBrowserDiagnostic = {
  schemaVersion: 1;
  surface: 'dashboard' | 'progress';
  navIndex: number;
  isFirst: boolean;
  profile: 1 | 4;
  valid: boolean;
  runnerStart: number;
  runnerEnd: number;
  autTimeOrigin: number;
  clockSync: {
    runnerBefore: number;
    autNow: number;
    runnerAfter: number;
    offsetMin: number;
    offsetMax: number;
  };
  events: DiagnosticEvent[];
  requests: RequestSpan[];
  requestIds: string[];
  navigation: NavigationTiming | null;
  longTasks: { startTime: number; duration: number }[];
  domReadyAt: number | null;
  selfCostMs: number;
  runnerSelfCostMs: number;
  dropped: number;
  unsupported: (
    | 'navigation-timing'
    | 'longtask'
    | 'mutation-observer'
    | 'fetch-hook'
    | 'clock-sync'
  )[];
};
type Options = {
  navIndex: number;
  profile: 1 | 4;
  runnerStart: number;
  runnerNow: () => number;
} & (
  | {
      surface?: 'dashboard';
      oracle: {
        completed: number;
        required: number;
        attempts: number;
        students: number;
      };
    }
  | {
      surface: 'progress';
      oracle: {
        studentCompleted: number;
        studentRequired: number;
        studentAttempts: number;
      };
    }
);
type Mark = { name: string; route?: string; requestId?: string };
type TimingWindow = Cypress.AUTWindow & {
  __alunzaPhaseTiming?: (mark: Mark, startedAt: number) => void;
};
export type PhaseBrowserCollector = {
  finish: (runnerEnd: number, valid: boolean) => PhaseBrowserDiagnostic;
};
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const limits = { events: 128, requests: 64, longTasks: 64 } as const;

/** Raw URLs are inspected transiently; only the allowlisted category survives. */
export function phaseDiagnosticRoute(
  pathname: string,
): PhaseDiagnosticRoute | null {
  if (pathname === '/api/v1/me') return 'identity';
  if (pathname === '/api/v1/me/progress') return 'progress';
  if (/^\/api\/v1\/classes\/[0-9a-f-]+$/i.test(pathname)) return 'class';
  if (/^\/api\/v1\/organizations\/[0-9a-f-]+$/i.test(pathname))
    return 'organization';
  if (/^\/api\/v1\/classes\/[0-9a-f-]+\/dashboard$/i.test(pathname))
    return 'dashboard';
  if (/^\/api\/v1\/classes\/[0-9a-f-]+\/signals$/i.test(pathname))
    return 'signals';
  if (pathname === '/auth/v1/token') return 'auth-token';
  if (pathname === '/auth/v1/user') return 'auth-user';
  if (pathname === '/auth/v1/logout') return 'auth-logout';
  return null;
}

export function installPhaseBrowserDiagnostics(
  window: TimingWindow,
  options: Options,
): PhaseBrowserCollector {
  const now = () => window.performance.now();
  const installedAt = now();
  const surface = options.surface ?? 'dashboard';
  const runnerBefore = options.runnerNow();
  const autNow = now();
  const runnerAfter = options.runnerNow();
  const events: DiagnosticEvent[] = [];
  const requests: RequestSpan[] = [];
  const longTasks: PhaseBrowserDiagnostic['longTasks'] = [];
  const unsupported: PhaseBrowserDiagnostic['unsupported'] = [];
  let selfCostMs = 0,
    dropped = 0,
    domReadyAt: number | null = null,
    closed = false;
  let mutation: MutationObserver | undefined,
    longObserver: PerformanceObserver | undefined;
  let root: Element | null = null;
  const originalFetch = window.fetch;
  const originalMark = window.__alunzaPhaseTiming;
  function unsupportedOnce(
    name: PhaseBrowserDiagnostic['unsupported'][number],
  ) {
    if (!unsupported.includes(name)) unsupported.push(name);
  }
  function measured(action: () => void, startedAt = now()) {
    if (closed) return;
    try {
      action();
    } catch {
      dropped++;
    } finally {
      selfCostMs += Math.max(0, now() - startedAt);
    }
  }
  function appendEvent(event: DiagnosticEvent) {
    if (events.length < limits.events) events.push(event);
    else dropped++;
  }
  const mark = (value: Mark, startedAt: number) =>
    measured(() => {
      if (
        !phaseDiagnosticEvents.includes(value.name as EventName) ||
        !Number.isFinite(startedAt)
      ) {
        dropped++;
        return;
      }
      if (
        value.route !== undefined &&
        !phaseDiagnosticRoutes.includes(value.route as PhaseDiagnosticRoute)
      ) {
        dropped++;
        return;
      }
      if (value.requestId !== undefined && !uuid.test(value.requestId)) {
        dropped++;
        return;
      }
      appendEvent({
        name: value.name as EventName,
        at: startedAt,
        ...(value.route ? { route: value.route as PhaseDiagnosticRoute } : {}),
        ...(value.requestId ? { requestId: value.requestId } : {}),
      });
    }, startedAt);
  try {
    window.__alunzaPhaseTiming = mark;
  } catch {
    dropped++;
  }
  appendEvent({ name: 'observer:installed', at: autNow });

  const wrappedFetch: typeof window.fetch = function (this: unknown, ...args) {
    let span: RequestSpan | undefined;
    measured(() => {
      const [input, init] = args;
      const url =
        typeof input === 'string'
          ? input
          : input instanceof window.URL
            ? input.href
            : input.url;
      const route = phaseDiagnosticRoute(
        new window.URL(url, window.location.href).pathname,
      );
      if (!route) return;
      if (requests.length >= limits.requests) {
        dropped++;
        return;
      }
      const method =
        init?.method ??
        (typeof input === 'object' && 'method' in input ? input.method : 'GET');
      span = {
        seq: requests.length,
        route,
        method: method === 'GET' || method === 'POST' ? method : 'OTHER',
        start: now(),
        headers: null,
        end: null,
        status: null,
        requestId: null,
        outcome: 'pending',
        aborted: null,
      };
      requests.push(span);
    });
    // Preserve the exact receiver, argument count, promise, Response and errors.
    let result: ReturnType<typeof window.fetch>;
    try {
      result = Reflect.apply(originalFetch, this, args);
    } catch (error) {
      measured(() => {
        if (span) {
          span.end = now();
          span.outcome = 'rejected';
          span.aborted = false;
        }
      });
      throw error;
    }
    if (span)
      measured(() => {
        void result.then(
          (response) =>
            measured(() => {
              if (!span) return;
              span.headers = now();
              span.end = span.headers;
              span.status = response.status;
              span.outcome = 'fulfilled';
              span.aborted = false;
              const requestId = response.headers.get('X-Request-Id');
              span.requestId =
                requestId && uuid.test(requestId) ? requestId : null;
            }),
          () =>
            measured(() => {
              if (!span) return;
              const [input, init] = args;
              span.end = now();
              span.outcome = 'rejected';
              span.aborted =
                init?.signal?.aborted ??
                (typeof input === 'object' && 'signal' in input
                  ? input.signal.aborted
                  : false);
            }),
        );
      });
    return result;
  };
  try {
    window.fetch = wrappedFetch;
  } catch {
    unsupportedOnce('fetch-hook');
  }

  function checkDom() {
    if (domReadyAt !== null) return;
    const found = window.document.querySelector(
      surface === 'progress'
        ? '[data-cy="student-progress"]'
        : '[data-cy="class-dashboard"]',
    );
    if (!found) return;
    if (root !== found) {
      root = found;
      mutation?.disconnect();
      mutation?.observe(root, {
        childList: true,
        subtree: true,
        characterData: true,
      });
    }
    let ready: boolean;
    if (options.surface === 'progress') {
      // Mirror ready() without adding an assertion, wait or paint boundary.
      ready =
        !!root
          .querySelector('[data-cy="progress-summary"]')
          ?.textContent?.includes(
            `${options.oracle.studentCompleted}/${options.oracle.studentRequired}`,
          ) &&
        root.querySelectorAll('[data-cy="progress-recent-attempt-row"]')
          .length === Math.min(options.oracle.studentAttempts, 50);
    } else {
      const summary = root.querySelector('[data-cy="dashboard-summary"]');
      ready =
        !!summary?.textContent?.includes(
          `${options.oracle.completed}/${options.oracle.required}`,
        ) &&
        summary.querySelector('[data-cy="dashboard-period-attempts"]')
          ?.textContent === String(options.oracle.attempts) &&
        root.querySelectorAll('[data-cy="dashboard-student-row"]').length ===
          Math.min(options.oracle.students, 50) &&
        !!root.querySelector(
          '[data-cy="dashboard-signals"] [data-cy="dashboard-processing"]',
        ) &&
        root.querySelectorAll('[data-cy="dashboard-signal-row"]').length === 50;
    }
    if (ready) {
      domReadyAt = now();
      appendEvent({ name: 'dom:ready', at: domReadyAt });
      mutation?.disconnect();
    }
  }
  try {
    mutation = new window.MutationObserver(() => measured(checkDom));
    mutation.observe(window.document, { childList: true, subtree: true });
    checkDom();
  } catch {
    unsupportedOnce('mutation-observer');
  }
  function appendLongTasks(entries: PerformanceEntry[]) {
    for (const entry of entries) {
      if (longTasks.length < limits.longTasks)
        longTasks.push({
          startTime: entry.startTime,
          duration: entry.duration,
        });
      else dropped++;
    }
  }
  try {
    if (!window.PerformanceObserver?.supportedEntryTypes.includes('longtask'))
      unsupportedOnce('longtask');
    else {
      longObserver = new window.PerformanceObserver((list) =>
        measured(() => appendLongTasks(list.getEntries())),
      );
      longObserver.observe({ type: 'longtask', buffered: true });
    }
  } catch {
    unsupportedOnce('longtask');
  }
  selfCostMs += Math.max(0, now() - installedAt);
  let completed: PhaseBrowserDiagnostic | undefined;
  return {
    finish(runnerEnd, valid) {
      if (completed) return completed;
      // Called only after the original gate stopwatch stops (also on failure).
      const collectionStarted = options.runnerNow();
      closed = true;
      try {
        mutation?.disconnect();
      } catch {
        unsupportedOnce('mutation-observer');
      }
      try {
        if (longObserver) {
          appendLongTasks(longObserver.takeRecords());
          longObserver.disconnect();
        }
      } catch {
        unsupportedOnce('longtask');
      }
      try {
        if (window.fetch === wrappedFetch) window.fetch = originalFetch;
      } catch {
        unsupportedOnce('fetch-hook');
      }
      try {
        if (window.__alunzaPhaseTiming === mark) {
          if (originalMark) window.__alunzaPhaseTiming = originalMark;
          else delete window.__alunzaPhaseTiming;
        }
      } catch {
        dropped++;
      }
      let navigation: NavigationTiming | null = null;
      try {
        const entry = window.performance.getEntriesByType('navigation')[0] as
          PerformanceNavigationTiming | undefined;
        if (entry)
          navigation = {
            startTime: entry.startTime,
            responseEnd: entry.responseEnd,
            domInteractive: entry.domInteractive,
            domContentLoadedEventEnd: entry.domContentLoadedEventEnd,
            loadEventEnd: entry.loadEventEnd,
          };
        else unsupportedOnce('navigation-timing');
      } catch {
        unsupportedOnce('navigation-timing');
      }
      completed = {
        schemaVersion: 1,
        surface,
        navIndex: options.navIndex,
        isFirst: options.navIndex === 0,
        profile: options.profile,
        valid,
        runnerStart: options.runnerStart,
        runnerEnd,
        autTimeOrigin: window.performance.timeOrigin,
        clockSync: {
          runnerBefore,
          autNow,
          runnerAfter,
          offsetMin: runnerBefore - autNow,
          offsetMax: runnerAfter - autNow,
        },
        events: events.map((event) => ({ ...event })),
        requests: requests.map((request) => ({ ...request })),
        requestIds: [
          ...new Set(
            requests.flatMap((request) =>
              request.requestId ? [request.requestId] : [],
            ),
          ),
        ],
        navigation,
        longTasks: longTasks.map((entry) => ({ ...entry })),
        domReadyAt,
        selfCostMs,
        runnerSelfCostMs: 0,
        dropped,
        unsupported: [...unsupported],
      };
      completed.runnerSelfCostMs = Math.max(
        0,
        options.runnerNow() - collectionStarted,
      );
      return completed;
    },
  };
}
